insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('welltest', 'advanced', 'module', 'm01-regression', 1, 'What does a model fit do that a straight-line analysis cannot?', '["Determine the flow regime, since the fit selects whichever model matches the data best.", "Use the storage-affected data, because the model includes wellbore storage explicitly.", "Remove the dependence on the reservoir inputs, since the fit adjusts them along with the parameters.", "Give a result without a diagnosis, since the catalog covers every response a reservoir can produce."]'::jsonb, 1, 'Those twenty-seven storage-affected points are where the storage coefficient comes from. The straight line has to discard them and then has no way to report C at all.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 2, 'Why is there no asymptotic bias in a model fit?', '["Because the least squares fit is unbiased by construction when the residuals are independent.", "Because the bias cancels between the pressure and derivative blocks of the residual vector.", "Because the log residual weights every decade equally, which removes the late-time bias.", "Because the model evaluates the full solution at every time rather than an asymptote of it."]'::jsonb, 3, 'The straight line converges towards the radial asymptote from one side and stops when the data run out. There is no asymptote for the model to converge to.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 3, 'The homogeneous fit on the buildup recovers all three parameters to six figures. What does that demonstrate?', '["That the optimiser works and the model is implemented correctly, which is what a fixture is for.", "That a regression on a real well test recovers the reservoir to a similar precision.", "That the confidence intervals from a regression are reliable when the fit converges.", "That the derivative residuals are unnecessary, since the pressure alone determines the whole answer."]'::jsonb, 0, 'The fixture was generated by the same solution the model evaluates, with no noise. What survives the move to real data is the structural advantage, not the precision.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 4, 'Why does the engine use logarithmic residuals?', '["So that negative model values are penalised automatically rather than crashing the fit.", "So that the residual vector is dimensionless and the two blocks can be combined.", "So that a one percent discrepancy contributes the same amount wherever on the plot it occurs.", "So that the optimiser''s steps are multiplicative, which suits parameters spanning many decades."]'::jsonb, 2, 'A plain least squares would be dominated by the late data, where the pressure changes are largest, and the early data carry the storage and much of the skin.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 5, 'What happens when a model value comes out non-positive during a fit?', '["The fit aborts and returns null, since the parameter set is outside the physical range.", "A fixed penalty of 5 is charged in place of the undefined logarithm.", "The point is dropped from the residual vector for that iteration only.", "The bounds are tightened automatically so that the optimiser cannot revisit that region."]'::jsonb, 1, 'That keeps the optimiser away from parameter regions that produce non-physical output without letting it crash, which is what a penalty term is for.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 6, 'Why does the residual vector include the derivative as well as the pressure?', '["Because the derivative carries the permeability directly through its plateau height.", "Because fitting two quantities halves the confidence interval on each parameter.", "Because the derivative is what a diagnostician looks at, so the fit should match what is seen.", "Because pressure is an integral and can hide a shape error that the derivative makes visible."]'::jsonb, 3, 'A fit on pressure alone will accept a model whose shape is wrong provided the total pressure change comes out right, and shape is where the diagnosis lives.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 7, 'What is the derivative weight for?', '["Trading the derivative''s noise against its shape information, which matters on real data.", "Balancing the two residual blocks so that they have the same number of terms.", "Compensating for the factor of 2.303 between the derivative and the semilog slope.", "Suppressing the derivative at early times, where the Bourdet rule is least reliable."]'::jsonb, 0, 'On this noiseless buildup the weight barely matters: dropping the derivative entirely still recovers all three parameters to six figures. It is a noise decision rather than a physics one.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 8, 'Two fits of the same data report different sums of squared residuals. When is that comparison meaningful?', '["Whenever both fits converged, since a converged residual is at a local minimum by definition.", "Whenever the two models have the same number of parameters, so the degrees of freedom match.", "Only when the residual definition, the weighting and the smoothing were identical.", "Always, since the residual is computed from the same data in both cases."]'::jsonb, 2, 'Change the objective and the ranking of two candidate models can change. Comparing residuals from fits run with different settings is a common and meaningless exercise.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 9, 'Which parameters does the catalog fit on a logarithmic scale?', '["All of them, since every physical parameter in the catalog is positive by definition.", "Permeability, storage, fracture half-length and the dual-porosity parameters.", "Only permeability and storage, which are the two that span the most decades.", "None: the log scaling is applied to the residuals rather than to the parameters."]'::jsonb, 1, 'Skin is not, because it can legitimately be negative and its natural scale is additive. Log scaling enforces positivity for free and makes the intervals multiplicative.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 10, 'Why is the skin bounded at zero for every model except the homogeneous one?', '["Because a negative skin makes the Stehfest inversion numerically unstable in those models.", "Because a stimulated well cannot exist in a fissured reservoir or near a boundary.", "Because the catalog''s authors judged negative skins too rare in those settings to be worth supporting.", "Because the effective-radius mapping for a negative skin does not commute with image wells or fissure functions."]'::jsonb, 3, 'The homogeneous model handles a negative skin by the effective-radius route, and a fracture model represents the stimulation explicitly rather than as a skin.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 11, 'What does a fitted parameter sitting exactly on a bound tell you?', '["That the model wants to go further and cannot, so the value is a limit not a measurement.", "That the optimiser has converged, since a bound is a stationary point of any constrained problem.", "That the bound was set too tight and should be widened before the result is used.", "That the parameter is well determined, since the data have pushed it against a physical limit."]'::jsonb, 0, 'Widening the bound is sometimes right and sometimes not. If the bound is physical, the model is being asked to represent something it cannot.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 12, 'Starting the buildup fit from 5 mD and 0.5 bbl per psi lands in the same place. What does that show?', '["That the bounds are doing the work, by preventing the optimiser from leaving the correct basin.", "That the starting values in the catalog are irrelevant and could be removed.", "That the problem is well conditioned, with one clear minimum the optimiser finds from anywhere sensible.", "That the residual surface is convex, which guarantees convergence from any starting point."]'::jsonb, 2, 'Remember what a well-conditioned problem looks like, because the next module is entirely about problems that are not like this one.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 13, 'Which parameter does the straight-line method never report?', '["The skin, which requires a model rather than a line to separate from the permeability.", "The wellbore storage coefficient, which it treats as a nuisance to be waited out.", "The extrapolated pressure, which only a regression can provide from the whole record.", "The flow capacity, which the fit reports directly while a line gives only a permeability."]'::jsonb, 1, 'A storage coefficient much larger than the wellbore volume implies means a liquid level or gas cap in the annulus. One that changes during the test means the superposition assumption is broken.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 14, 'A real fit whose residual reaches machine precision means what?', '["The model is exactly correct and the gauge was exceptionally precise.", "The optimiser has overfitted and the parameters should be regularised.", "The residual was computed in log space, which compresses the differences.", "The data were synthetic, or the model has more parameters than the data support, or the comparison is wrong."]'::jsonb, 3, 'A good fit on real data has visible residual scatter and a residual set by the noise level, with intervals of a few percent on permeability and wider on everything else.'),
  ('welltest', 'advanced', 'module', 'm01-regression', 15, 'What does the regression NOT decide?', '["The starting values, which the catalog supplies as defaults for every parameter.", "The parameter bounds, which are fixed metadata rather than a fitting decision.", "Which model to fit, which is the interpretation and comes from the diagnosis.", "The smoothing window, which is a data preparation choice made before the fit."]'::jsonb, 2, 'Its willingness to fit any model you name is the single most dangerous property it has, and every failure in the next module comes from a model the diagnosis did not justify.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 1, 'How is the fit''s confidence interval constructed?', '["From the spread of the parameters across repeated fits with perturbed starting values.", "From the range of parameters that keep the residual within a stated factor of its minimum.", "From the curvature of the objective near its minimum, scaled by the residual variance itself.", "From the gauge specification propagated forward through the model''s sensitivity to each parameter."]'::jsonb, 2, 'Every step of that construction is correct. It is a correct answer to a question about how well the optimiser converged.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 2, 'What question does the fit''s confidence interval actually answer?', '["Given that this model is right and the residual scatter is the measurement error, how precisely is each parameter determined?", "What range of each parameter is consistent with the data at 95 percent confidence?", "How much would each parameter move if the reservoir inputs were varied over their uncertainty?", "How reproducible is the answer if the test were repeated on the same well next week?"]'::jsonb, 0, 'On this fixture the residual scatter IS machine precision, because the data are the model evaluated at those parameters, so the answer comes back extremely precise.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 3, 'Which of the interval''s assumptions is usually the dominant error on real data?', '["That the residuals are independent, which gauge noise correlation violates.", "That the model is correct, which on a real test it never exactly is.", "That the objective is quadratic near the minimum, which fails for badly scaled parameters.", "That the parameters are uncorrelated, which the covariance matrix already accounts for."]'::jsonb, 1, 'The interval has no term for model error, and it is usually far larger than the scatter. Nor does it know about the rate, the net pay, the viscosity or the compressibility.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 4, 'Where does a reported 95 percent interval still carry useful information?', '["When the residual is at the noise level, which means the model has been correctly identified.", "When it is wider than the range implied by the input uncertainties, which then dominate.", "When the fit converged, since a converged fit''s covariance is the true parameter covariance.", "For comparing parameters within one fit, and for spotting one the data do not constrain at all."]'::jsonb, 3, 'An interval that runs to a bound, or that is wider than the parameter''s plausible range, is a genuine warning. The next question is a case where no warning fires at all.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 5, 'Fitting the sealing-fault model to the buildup, which has no boundary, does what?', '["Fails to converge, because the fault distance has no minimum in the objective function.", "Drives the fault distance to its upper bound of 50000 ft, which is how this model says there is none.", "Converges, reports the right permeability and skin, and locates a fault to within a few tens of feet.", "Returns the same result as the homogeneous model, since the extra parameter has no effect."]'::jsonb, 2, 'It pushes the fault far enough that its effect is small, and stops wherever the last few parts in a trillion of misfit are best absorbed.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 6, 'Writing the same pressure change two arithmetically equivalent ways moves the fitted fault by how much?', '["About 4.5e-13 ft, which is the size of the difference in the data itself.", "About 116 ft, to a confidence interval that does not overlap the first one.", "Not at all, because the two data sets are identical to within floating point precision.", "About 2 ft, which is well inside the confidence interval the fit reports."]'::jsonb, 1, 'The two ways of writing the pressure change differ by at most 4.5e-13 psi. The permeability does not move at all; the fault distance is decided by rounding.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 7, 'What does that experiment prove about the two parameters?', '["The permeability is constrained by the data and the fault distance is not.", "The fit is numerically unstable and should be run with tighter convergence tolerances.", "The sealing-fault model is wrongly implemented at large distances.", "The confidence interval is too narrow and should be widened by the condition number."]'::jsonb, 0, 'The objective function is essentially flat along the fault direction, so the optimiser stops on a plateau, and the curvature-based interval reports a tight range around wherever it stopped.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 8, 'Why is the phantom fault distance taught but never graded?', '["Because it depends on the engine version, and a graded field has to survive an upgrade.", "Because it is a negative result, and the course grades only quantities that are correct.", "Because the tolerance would have to be wider than the value, which the grader cannot express.", "Because no learner could reproduce it, which is exactly the point being made."]'::jsonb, 3, 'The graded regression field is the fault that is actually there: the same model fitted to the fault fixture, which moves by two hundredths of a foot under the same rewrite.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 9, 'Why does an extra parameter always improve the fit?', '["Because the least squares objective decreases monotonically with the number of parameters by construction.", "Because it can always be set to a value that does no harm, and it usually finds something better.", "Because the additional degree of freedom absorbs the noise, which lowers the residual.", "Because bounded optimisers explore a larger region when more parameters are present."]'::jsonb, 1, 'So a lower residual does not favour the more complex model. Comparing models with different parameter counts needs a penalty, which is what the information criteria provide.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 10, 'Which test distinguishes a constrained parameter from an unconstrained one in practice?', '["Compare the confidence intervals, since an unconstrained parameter has the wider one.", "Check whether the parameter reached a bound, which is what an unconstrained one does.", "Perturb the data slightly and refit: constrained parameters do not move and unconstrained ones do.", "Compute the correlation matrix, since an unconstrained parameter is uncorrelated with all the others."]'::jsonb, 2, 'It takes two runs and it answers the question the confidence interval cannot. On the buildup, the permeability does not move and the fault distance moves 116 ft.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 11, 'Fitting dual porosity to the homogeneous buildup drives omega where?', '["To its lower bound of 0.001, which removes the fissure storage entirely.", "To the middle of its range, since the data contain no information about it.", "To a value near 0.08, which is the storativity ratio of the other fixture.", "To its upper bound of 1, which IS the homogeneous case."]'::jsonb, 3, 'The model has been asked to describe a reservoir with no second porosity, and putting omega on the bound that removes it is the only way this model can say so.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 12, 'That fit reports converged as false. Why?', '["Because a parameter pinned against a bound cannot move, so the gradient test is never satisfied.", "Because the residual is still falling when the iteration limit is reached.", "Because omega and lambda are strongly correlated, so the covariance matrix is singular.", "Because the model produces a non-physical response at omega equal to 1, triggering the penalty."]'::jsonb, 0, 'The right answer, labelled a failure. When a fit reports failure, look at the bounds before concluding the data are bad.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 13, 'Which of these is a success wearing a failure''s clothes?', '["A parameter sitting at a bound with the other parameters visibly distorted.", "No parameter at a bound and a large residual that will not come down.", "A parameter at a bound with all the other parameters sensible.", "A converged fit with a residual at machine precision on real gauge data."]'::jsonb, 2, 'The second is a genuine failure of the model catalog, and the third is a genuine failure of the interpretation. Only the first means the model is over-specified and a simpler one will do.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 14, 'Which kind of model degrades safely when it is over-specified?', '["One whose extra parameters are fitted on a logarithmic scale, which prevents runaway values.", "One whose extra parameters have a value that makes them vanish, as omega equal to 1 does.", "One with fewer parameters than data points, which is every model in the catalog.", "One whose extra parameters are bounded, since a bound stops the parameter inventing structure."]'::jsonb, 1, 'A fault distance has no null value inside its bounds: no finite distance removes the fault. That is why a boundary model does not degrade safely and a dual-porosity model does.'),
  ('welltest', 'advanced', 'module', 'm02-what-a-fit-cannot-tell-you', 15, 'What is the one item in an honest fit report that would most quickly expose a phantom parameter?', '["The confidence intervals, which are narrow for constrained parameters and wide otherwise.", "The convergence flag, since a fit with an unconstrained parameter usually fails to converge.", "The residual, since a phantom parameter leaves the residual essentially unchanged.", "The perturbation check, reporting which parameters moved when the data or window were changed slightly."]'::jsonb, 3, 'The residual IS essentially unchanged, and that is the point: on this buildup it improved by a factor of hundreds of thousands from a value already at machine precision, which is nothing.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 1, 'In the general superposition formula, what weights each step''s response?', '["The CHANGE in rate at that step, rather than the rate in force during it.", "The rate in force during that step, normalised by the current rate at the evaluation time.", "The duration of the step, so that longer periods contribute proportionally more.", "The cumulative up to that step over the total."]'::jsonb, 0, 'Steps that have not happened yet contribute nothing, and a step where the rate did not change contributes nothing, which is why the engine collapses repeated rates.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 2, 'What does superposeDeltaP contain that is specific to buildups?', '["A branch that applies the Horner transform when the final rate is zero.", "A term for the changed storage coefficient after a well is shut in at surface.", "The Agarwal equivalent time transform, which is applied to shut-in periods only.", "Nothing at all: a shut-in is a step to zero rate and the machinery is the same."]'::jsonb, 3, 'That generality is the point. The two-well picture of a buildup in the Associate tier is the two-step special case of this formula.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 3, 'Why is the three-rate fixture generated by the engine rather than supplied as data?', '["Because a real multi-rate dataset would carry noise that obscures the point being made.", "So that the engine generates it, the engine recovers it, and the gap between the two is the teaching result.", "Because the goldens file has no multi-rate fixture and adding one would change the engine tests.", "Because superposition is exact, so a generated response is indistinguishable from a real one."]'::jsonb, 1, 'The data are produced by a function whose implementation you can read, from parameters stated in the lesson. Nothing is asserted.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 4, 'What breaks superposition in a real buildup?', '["A rate history with more than three steps, beyond which the summation becomes ill conditioned.", "A skin large enough that the near-well pressure drop dominates the response.", "A storage coefficient that differs between the flowing and the shut-in conditions.", "A boundary being felt, since an image well is itself a superposition and the two interfere."]'::jsonb, 2, 'Rate-dependent skin is the other, and both damage the early data after each rate change, which is the same part of the record storage damages anyway.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 5, 'What does detectFlowPeriods classify a negative rate as?', '["Injection, since the well is taking fluid rather than producing it.", "A data error, since a producing well cannot have a negative rate in the record.", "A shut-in, since the well is not producing during that period.", "A flow period with the sign discarded, because the analysis uses the magnitude."]'::jsonb, 0, 'The classification is trivial and the utility is not. Real rate histories arrive as daily rates and the analysis needs periods with the shut-ins identified before anything else.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 6, 'How is the equivalent producing time defined?', '["The sum of the durations of every flowing period, excluding the shut-ins between them.", "Cumulative production divided by the last rate that was non-zero before the shut-in.", "The duration of the final flow period, extended backwards to the previous rate change.", "The time at which the cumulative production would have been reached at the average rate."]'::jsonb, 1, 'The reasoning is that the recent history dominates the buildup response and the distant history is adequately represented by its cumulative effect.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 7, 'For the three-rate history, why is the equivalent producing time nearly twice the last period''s length?', '["Because the last rate is the highest one, so dividing by it lengthens the equivalent time.", "Because the shut-in itself is included in the cumulative up to the moment of the closing.", "Because the equivalent time is defined on a logarithmic scale rather than a linear one.", "Because the earlier production at other rates still counts towards the cumulative."]'::jsonb, 3, 'The last rate is the highest, which SHORTENS the equivalent time. The cumulative from three periods is what makes it long.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 8, 'A wrong producing time does what to a Horner analysis?', '["Moves both in proportion, since the whole Horner axis shifts by the same factor.", "Moves the permeability substantially, since the slope is computed on the transformed axis.", "Moves the extrapolated pressure substantially, and the permeability very little indeed.", "Moves neither, since tp cancels between the numerator and the denominator of the ratio."]'::jsonb, 2, 'A buildup whose permeability agrees with other estimates but whose extrapolated pressure looks wrong is pointing at the producing time, and the check takes one division.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 9, 'When is the single-tp Horner approximation poor?', '["When a short final rate period follows a long history at a very different rate.", "When the well has produced for years, since the cumulative then dominates the recent history.", "When the shut-in is much longer than the production, which compresses the Horner axis.", "When the rate during the final period varied by more than a few percent."]'::jsonb, 0, 'Also when the well was shut in shortly before the test, or when the rate changed shortly before shut-in. In all three, use full superposition instead.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 10, 'In the multi-rate semilog, what has left the permeability equation?', '["The viscosity, which cancels between the rate normalisation and the slope.", "The rate, which is now in the normalisation rather than in the slope equation.", "The thickness, since the multi-rate form determines flow capacity directly.", "The formation volume factor, which is absorbed into the superposition time function."]'::jsonb, 1, 'That is why this form works across periods at different rates: the rate-normalised drawdown is what is plotted, and its slope gives permeability per unit rate.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 11, 'Why does multiRateSemilogAnalysis exclude shut-in points?', '["Because the superposition time function is undefined when the current rate is zero.", "Because a shut-in point has no rate to normalise by, so it would divide by zero.", "Because shut-in data are storage-dominated and would contaminate the fit.", "Because analysing a shut-in is Horner''s job, and mixing the two conflates two reference conditions."]'::jsonb, 3, 'The rate in force is zero at a shut-in point, and the engine skips those points explicitly rather than letting the normalisation blow up.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 12, 'The multi-rate fit uses fifteen points out of thirty-seven. Why so few?', '["Because the engine limits the fit to fifteen points to keep the least squares well conditioned.", "Because only the third period''s points are usable, and it contains fifteen of them.", "Because each period has an early transient that must be excluded, so the window problem occurs three times.", "Because the superposition time function is only monotonic over that subset."]'::jsonb, 2, 'After each rate change the well goes through a storage transient exactly as at the start of a test. On real data you would choose them from the derivative computed against the superposition time.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 13, 'Analysing only the last period as a fresh drawdown reports what?', '["About 119 mD against a planted 85, with a skin nearly double the true value.", "About 60 mD, because earlier production has depleted the near-well region.", "About 85 mD, since the last period is long enough for the earlier history to have decayed.", "An unstable answer, since only three points fall inside the last period''s radial window."]'::jsonb, 0, 'The two earlier steps are a net production still in progress, and their combined response is flattening. A flatter line means a higher permeability.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 14, 'In which direction do the permeability and skin errors go when the rate history is ignored?', '["Both low, which is the same direction as the storage and sealing-fault errors.", "Both of them high: better rock and worse damage than the well actually has.", "Permeability high and skin low, since the two are inversely related through the formula.", "Permeability low and skin high, because the flatter line implies a larger near-well drop."]'::jsonb, 1, 'This is the third coordinated pair in the course. The storage error and the fault error both give a lower permeability and a smaller skin; this one goes the other way.'),
  ('welltest', 'advanced', 'module', 'm03-rate-history', 15, 'What is the one-line check on whether the single-period shortcut is safe?', '["Check that the last period is longer than one and a half decades of storage transient.", "Confirm that the rate changed by less than a factor of two at the last step.", "Compare the equivalent producing time against the duration of the last period.", "Verify that the r squared of the single-period fit exceeds that of the multi-rate fit."]'::jsonb, 2, 'If they are close, the earlier history contributed little and the shortcut is defensible. On the fixture the equivalent time is nearly twice the last period, so it is not.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 1, 'Why do the liquid well test equations fail for gas?', '["Because gas flows turbulently near the wellbore, which the Darcy formulation cannot represent.", "Because the gas rate is measured at surface conditions and the equations work at reservoir ones.", "Because viscosity and compressibility vary strongly with pressure, so the equation is no longer linear.", "Because gas has no formation volume factor, so the slope equation has an undefined term."]'::jsonb, 2, 'Non-Darcy flow is real and it appears in the apparent skin. The failure of the equations themselves is the pressure dependence of the coefficients.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 2, 'What is pseudo-pressure?', '["Twice the integral of pressure divided by viscosity times the z factor, from zero to p.", "The pressure squared, corrected for the deviation of the gas from ideal behaviour.", "The pressure divided by the z factor, which is what the material balance uses.", "The pressure at which an equivalent liquid would give the same flow rate."]'::jsonb, 0, 'Its units are psi squared per centipoise, which is not a pressure and does not behave like one. Values run into the hundreds of millions.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 3, 'The pressure-squared method is exact under what condition?', '["When the gas is ideal, so that the z factor is exactly one everywhere.", "When the product of viscosity and z factor is constant over the pressure range.", "When the pressure drawdown is small compared with the reservoir pressure.", "When the reservoir temperature is high enough that the gas remains single phase throughout."]'::jsonb, 1, 'It is a good approximation at low pressures, below about 2000 psia, where mu z happens to be nearly flat. The pressure method is the high-pressure limit instead.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 4, 'Between 2000 and 4000 psia in this course''s gas, what is the ratio of pseudo-pressures?', '["Exactly 4, since pseudo-pressure is proportional to pressure squared by construction.", "About 2, since pseudo-pressure grows roughly linearly with pressure at these conditions.", "About 5.3, since the rising viscosity increases the integrand faster than pressure squared.", "About 3.30, where pressure squared would say exactly 4."]'::jsonb, 3, 'The integrand is 2p over mu z. At high pressure both mu and z rise, so it grows more slowly than p, and the pressure-squared shortcut overstates the drive by about a fifth.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 5, 'How does the engine compute pseudo-pressure?', '["By analytic integration of the Papay correlation, which has a closed-form antiderivative.", "By Gaussian quadrature between the tabulated points, which is exact for the cubic form.", "By trapezoid integration up a table of z and viscosity against pressure.", "By solving a differential equation whose right-hand side is the integrand."]'::jsonb, 2, 'The two runs in this course agree to about four parts in a hundred thousand because they used different meshes. A transform is a numerical procedure with its own error.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 6, 'Why does the engine provide an inverse of the pseudo-pressure function?', '["Because a gas buildup''s extrapolated pressure comes out in pseudo-pressure space and is not reportable.", "Because the material balance needs pressure while the analysis needs pseudo-pressure.", "Because the derivative must be computed in pressure space to be comparable with a liquid test.", "Because the pseudo-pressure table has to be inverted to find the reservoir temperature."]'::jsonb, 0, 'A p star of 4.8e8 in a report is a pseudo-pressure that somebody forgot to convert, and it is recognisable by its magnitude.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 7, 'What is gas compressibility, as the engine computes it?', '["The inverse of the pressure, which is exact for an ideal gas and adequate for a real one.", "One over pressure minus the fractional change of the z factor with pressure.", "The derivative of density with respect to pressure divided by the density at that state.", "The reciprocal of the bulk modulus, evaluated at reservoir temperature and pressure."]'::jsonb, 1, 'It matters because ct appears in the skin equation and the radius of investigation, and it varies strongly with pressure. Using a constant evaluated at the wrong pressure is a silent error.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 8, 'What does the equivalent-liquid adapter''s formation volume factor represent?', '["The volume a standard cubic foot of gas occupies at reservoir conditions.", "The ratio of the gas formation volume factor to that of the equivalent liquid.", "The conversion between the surface and reservoir rates for the gas being produced.", "Nothing physical: it is the constant that turns the liquid equations into the gas ones."]'::jsonb, 3, 'It comes out in the hundreds of thousands and it looks like a catastrophic input error, which is why the engine''s file header documents the substitution explicitly.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 9, 'Which quantities from a gas analysis come out in the units their names suggest?', '["All of them, since the adapter converts back before returning the result.", "Only the permeability, since the skin is an apparent skin with a rate-dependent term in it.", "The permeability, the flow capacity and the skin, and nothing else.", "None of them, since every quantity is in pseudo-pressure space until it is inverted."]'::jsonb, 2, 'The skin is an apparent skin, which is a caveat about its meaning rather than about its units. The one-hour value, p star and the slope are all in pseudo-pressure space.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 10, 'What is the apparent skin from a single-rate gas test?', '["The real skin plus the partial penetration pseudoskin, which the completion record separates.", "The real skin plus a term proportional to rate, which no single test can separate.", "The real skin corrected for the non-Darcy effect, which the engine removes internally.", "The real skin evaluated at the flowing pressure rather than at initial conditions."]'::jsonb, 1, 'Separating them needs the apparent skin at two or more rates: the intercept is the real skin and the slope is the non-Darcy coefficient. The engine has no function for it.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 11, 'What is a flow-after-flow test?', '["A sequence of stabilised rates with their flowing pressures, run to establish deliverability.", "A test in which the well is flowed, shut in, and flowed again at the same rate to check repeatability.", "A drawdown followed immediately by a buildup, analysed together by superposition.", "A sequence of short flows at increasing rates with shut-ins between them to restore pressure."]'::jsonb, 0, 'The last of those is an isochronal test, which gets around the requirement for stabilisation in a low-permeability gas reservoir.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 12, 'What does the Rawlins and Schellhardt exponent n mean?', '["It is the number of flow periods used in the fit, which sets the confidence in any extrapolation.", "It is the ratio of the turbulent to the laminar pressure drop at the tested rates.", "It is a shape factor for the drainage geometry, analogous to the Dietz factor.", "It runs from 1 for laminar flow down to 0.5 for fully turbulent, and real wells sit between."]'::jsonb, 3, 'The engine flags a fit whose n falls outside the physical range, which is a useful check that the stabilised pressures really were stabilised.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 13, 'What does the LIT or Houpeurt form have that the back-pressure form does not?', '["A closed-form absolute open flow, which the back-pressure form has to solve numerically.", "Validity well outside the tested rate range, which is guaranteed by its theoretical derivation.", "Coefficients with meanings: one carries the permeability and skin, the other the turbulence.", "Independence from the average reservoir pressure, which the back-pressure form requires."]'::jsonb, 2, 'It is derived from the gas flow equation with a turbulence term rather than fitted empirically, and it extrapolates more conservatively.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 14, 'What is absolute open flow?', '["The maximum rate the well can produce without damaging the completion.", "The rate the well would produce with the flowing pressure brought to atmospheric.", "The rate at which the well produces when the choke is fully open at surface.", "The rate corresponding to the largest pressure-squared difference actually tested."]'::jsonb, 1, 'Nobody flows a gas well to atmospheric pressure. It is a standardised index of capacity, and its value comes from being computed the same way everywhere.'),
  ('welltest', 'advanced', 'module', 'm04-gas', 15, 'The two deliverability methods disagree by about four percent on the same three points. Why?', '["Because the absolute open flow is an extrapolation to nearly twice the largest tested value.", "Because the back-pressure fit uses logarithms and the LIT fit does not, so they weight the points differently.", "Because the three points are too few to determine two parameters plus an exponent reliably.", "Because the LIT form ignores the base pressure, which the back-pressure form includes."]'::jsonb, 0, 'Nothing in either fit constrains behaviour outside the tested range, and the fit statistic cannot report on a region it never saw. The one with the better r squared returns the larger number.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 1, 'What does a long production history measure that a three-day buildup does not?', '["The permeability, more accurately, because a longer record averages a larger volume.", "The volume connected to the well, because the well has depleted enough of it for the depletion to show.", "The skin, more reliably, since it can be tracked over time rather than measured once.", "The boundary distances, since production data always reach the boundaries eventually."]'::jsonb, 1, 'A buildup tells you about the rock. A year of production tells you about the tank. Neither substitutes for the other.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 2, 'What time unit do the engine''s rate transient functions use?', '["Hours, for consistency with the rest of the well test module.", "Months, since production data are usually allocated monthly.", "Dimensionless time, so that the two sides of the studio can share the same functions.", "Days, while the pressure transient side of the studio stays in hours."]'::jsonb, 3, 'Mixing them is a factor-of-24 error that produces plausible-looking nonsense, which is why the module header states the convention.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 3, 'How is material-balance time defined?', '["Cumulative production divided by the current rate.", "The elapsed time weighted by the ratio of the current rate to the initial rate.", "The cumulative production divided by the initial rate, which normalises the whole history.", "The integral of the rate divided by the integral of the pressure drawdown."]'::jsonb, 0, 'It is the exact superposition time of boundary-dominated flow, so a variable-rate history plotted against it collapses onto the constant-rate solution.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 4, 'On the 80-day oil fixture, material-balance time reaches over 2354 days. What is that?', '["An error, since a time transform cannot exceed the elapsed time of the record.", "The effect of the trapezoid rule accumulating error over eighty integration steps.", "The transform working, because the rate has fallen a long way and the cumulative is divided by a small current rate.", "The point at which the well would deplete completely at its current rate."]'::jsonb, 2, 'The well HAS depleted as much as a constant-rate well would have by then. Reading it as a time is the same category error as reading a superposition time function as a time.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 5, 'What are the two answers from the oil flowing material balance line?', '["Permeability from the slope, and skin from the intercept, as in a semilog analysis.", "Oil in place from the slope, and productivity index from the intercept.", "Drainage area from the slope, and total compressibility from the intercept.", "Oil in place from the intercept, and the decline rate from the slope."]'::jsonb, 1, 'N equals one over the slope times ct, and J equals one over the intercept. One straight line, two numbers a reservoir engineer wants.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 6, 'Why is the flowing material balance exact for any rate history?', '["Because the rate normalisation removes the rate dependence before the line is fitted.", "Because material-balance time was constructed to make the relationship exact by definition.", "Because boundary-dominated flow is a steady state, in which the rate history no longer matters.", "Because the derivation combines the pseudo-steady-state drawdown with the material balance and never assumes a constant rate."]'::jsonb, 3, 'It requires the flow to be boundary-dominated, which is the one condition. That is what makes te the right time variable rather than a convenience.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 7, 'The first 40 rows give the same N as all 80, to fifteen figures. Why?', '["Because the last 40 rows carry almost no production, so they add nothing to the cumulative.", "Because the least squares fit is dominated by the early points in any case.", "Because this fixture is an exact constant-pressure exponential decline, for which the relation is an identity at every point.", "Because the analysis uses only the slope, which two points would determine exactly."]'::jsonb, 2, 'It is a property of this fixture rather than of production data, and the engine''s harness uses it as a gate. It is not a claim that half a record is always enough.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 8, 'A total compressibility 20 percent too high does what to N?', '["Makes it about 20 percent too high, since N is proportional to ct in the slope equation.", "Makes it about 17 percent too low, with no signature in the fit at all.", "Makes it about 17 percent too low, and the r squared falls visibly as a warning.", "Has no effect, since ct cancels between the material-balance time and the slope."]'::jsonb, 1, 'The line does not get worse. It is the same structural problem as the drainage area from a pressure transient, and it deserves the same treatment: report the compressibility.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 9, 'What does flowingMaterialBalanceOil do if the fitted slope comes out negative?', '["Refits without the early points, since a negative slope means the transient was included.", "Returns the magnitude, leaving the caller to notice that the sign was wrong.", "Raises an error naming the slope, which the calling code is expected to catch.", "Returns null rather than a negative oil in place, and says nothing about why."]'::jsonb, 3, 'A negative slope would give a negative oil in place. Returning null is the right behaviour and the caller has to check for it, since nothing is said.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 10, 'What does N from a flowing material balance actually describe?', '["The volume connected to this well under the conditions of this record.", "The oil in place in the drainage area assigned to the well by the field development plan.", "The recoverable reserves attributable to the well over its remaining life.", "The oil in place in the reservoir, divided among the wells by their production shares."]'::jsonb, 0, 'Summing N over the wells of a field is not the field''s oil in place, because drainage volumes overlap and unswept regions belong to nobody.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 11, 'Why does the gas version need a second transform?', '["Because pseudo-pressure alone cannot represent the two-phase behaviour of a wet gas.", "Because the gas rate is measured in Mscf per day rather than in reservoir volumes.", "Because gas viscosity and compressibility change so much during depletion that storage varies.", "Because the material balance for gas is p over z rather than p, which the time axis must match."]'::jsonb, 2, 'Pseudo-pressure linearises the coefficients. Pseudo-time handles the remaining non-linearity in the storage term, and for a production history over months it is not small.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 12, 'Why is the gas calculation circular?', '["Because the pseudo-pressure table depends on the reservoir temperature, which the fit also returns.", "Because pseudo-time needs the average pressure, which comes from a material balance needing G.", "Because the gas compressibility depends on the pressure, which depends on the compressibility.", "Because the rate-normalised drawdown uses m of pwf, which itself needs the gas in place."]'::jsonb, 1, 'It is resolved by iterating: guess G, compute the average pressure, compute pseudo-time, regress, get a new G, repeat until it stops moving.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 13, 'At the last row of the gas fixture, pseudo-time is about half of material-balance time. What does that mean?', '["That the reservoir has depleted by about half of its original gas in place.", "That the correction is second order and could reasonably be skipped for a first pass.", "That the iteration has not converged, since the two should agree once G is correct.", "That using material-balance time instead would put the slope out by nearly two."]'::jsonb, 3, 'It converged in fifteen iterations. mu ct for gas falls substantially as the reservoir depletes, and over a 300-day depletion the accumulated difference is a factor of two.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 14, 'Transient linear flow recovers which quantity exactly?', '["The product of the fracture half-length and the square root of the permeability.", "The fracture half-length, once the permeability is supplied from a radial analysis.", "The permeability, since the half-length cancels between the slope and the intercept.", "The fracture conductivity, which is what the linear flow period is sensitive to."]'::jsonb, 0, 'Fifteen significant figures on this fixture, at an r squared of 1. And it stops there: the split into two quantities is made by assumption.'),
  ('welltest', 'advanced', 'module', 'm05-rate-transient-analysis', 15, 'Why does the degeneracy in xf times root k matter so much in unconventionals?', '["Because shale permeabilities are too low for the sqrt-time slope to be resolved at all.", "Because the fracture half-length is the only parameter a completion engineer can control.", "Because a multi-fractured horizontal well may stay in linear flow for its whole life.", "Because boundary-dominated flow in shale arrives too early for the linear period to be seen."]'::jsonb, 2, 'Boundary-dominated flow, where the volume enters and the product splits, arrives after years or never. So the most-reported number in unconventional analysis is a product.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 1, 'What is the new class of error the Expert tier introduces?', '["A numerical error, since the Laplace inversion is approximate and its error is uncontrolled.", "A fit that reports parameters and confidence intervals for a model that was never justified.", "An overfitting error, in which the model reproduces the noise rather than the signal.", "A convergence error, in which the optimiser stops at a local minimum rather than the global one."]'::jsonb, 1, 'The regression will fit whatever model you give it. Its willingness to do so is the single most dangerous property it has.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 2, 'Which five failures did the course catalogue, all on correct data with correct arithmetic?', '["Storage in the window, a line past a fault, a fracture read as radial, a rate history ignored, and a parameter nothing constrained.", "A wrong rate, a wrong thickness, a wrong compressibility, a drifting gauge and an unrecorded shut-in.", "Storage, boundaries, heterogeneity, multiphase flow near the wellbore, and non-Darcy flow.", "Over-smoothing, under-smoothing, decimating too far, despiking too aggressively and extrapolating too far."]'::jsonb, 0, 'Every one of the five is a defensible-looking fit. The first four move the permeability; the fifth moves nothing and reports a boundary that does not exist.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Which of the five moves the permeability UP rather than down?', '["Only a rate history ignored; the fracture case reports a lower permeability.", "Only a fractured well read as radial; the rate history case reports a lower permeability.", "A fractured well read as radial, and a rate history that was ignored.", "None of them: every mis-specified analysis understates permeability."]'::jsonb, 2, 'Storage in the window and a line past a fault both understate it. The other two overstate it, and all four also move the skin in a coordinated way.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 4, 'Why does the course teach deconvolution and grade nothing about it?', '["Because deconvolution requires a rate history sampled more finely than production data provide.", "Because it is proprietary, so a course cannot describe the algorithms in enough detail.", "Because superposition already achieves the same result, so deconvolution adds nothing new.", "Because the engine has none, and because an ill-posed inversion is where the course could least certify an answer."]'::jsonb, 3, 'Superposition ASSUMES the constant-rate response shape; deconvolution extracts it. Every practical algorithm regularises the solution, which imposes smoothness the data did not require.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 5, 'What does deconvolution buy that superposition does not?', '["An exact treatment of variable storage, which superposition cannot represent.", "A single constant-rate response spanning the whole history, reaching boundaries no individual buildup came near.", "A model-free permeability, since no catalog model has to be selected.", "A confidence interval on the response itself rather than on the fitted parameters."]'::jsonb, 1, 'It is the reason modern interpretation can see drainage volumes from routine production data, and it is why its absence is worth stating.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 6, 'Why can this engine not do an interference test?', '["Because every model evaluates the pressure at the ACTIVE well only.", "Because it has no way to represent two wells producing at once in the same reservoir.", "Because the Stehfest inversion is too slow to evaluate at the distances involved.", "Because interference responses are too small to be resolved by the models'' precision."]'::jsonb, 0, 'The line-source function evaluates the dimensionless pressure at a dimensionless radius, which is the building block, and nothing is built on it for this purpose.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 7, 'What makes interference testing valuable?', '["It measures the permeability over a much larger volume than a single-well test.", "It requires no shut-in of the producing well, so it costs no deferred production.", "It constrains the permeability and storativity BETWEEN two wells.", "It gives the drainage area directly, since the two wells bound the region between them."]'::jsonb, 2, 'It is the most direct measurement of connectivity in the subsurface, and pulse testing refines it by separating the signal from background trends.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 8, 'What does the go-live migration for this course assert about the graded fields?', '["That every field''s tolerance is at least a thousand times the engine''s numerical precision.", "That the eighteen fields are distributed six per tier with no duplicate keys.", "That every field is reproducible from the vendored engine at its default settings.", "That no field key mentions deconvolution, interference or a non-Darcy or apparent skin."]'::jsonb, 3, 'It turns a scope commitment from a promise in a header into a check, which is the same device the fluids course used for its screening quantities.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Why does a gas well''s reported skin depend on the rate it was tested at?', '["Because the pseudo-pressure transform is evaluated at the flowing pressure, which varies with rate.", "Because the apparent skin contains a non-Darcy term proportional to rate.", "Because the storage coefficient changes with rate, which shifts the line''s position.", "Because the equivalent-liquid adapter uses the rate in its formation volume factor."]'::jsonb, 1, 'Comparing skins between gas wells tested at different rates compares different quantities, and separating the two needs an isochronal or multi-rate test.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 10, 'Which eight items does the course''s honest fit report contain?', '["Model and why, inputs, rate history, window and preparation, settings, parameters with bounds, residual and convergence, and a perturbation check.", "Model, parameters, confidence intervals, residual, plot, rate, thickness and a recommendation.", "Data source, gauge calibration, analyst, date, software version, model, parameters and uncertainty.", "Objective, method, results, discussion, conclusions, recommendations, references and appendices."]'::jsonb, 0, 'The perturbation check is two minutes of work and it is the single most informative item, because it says which parameters the data actually constrained.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 11, 'Which plot belongs in the report?', '["Semilog, with the fitted window highlighted and the extrapolation to p star shown.", "Cartesian pressure against time, which is where a boundary effect is most visible.", "Log-log, pressure change and derivative, data and model together.", "The residuals against time, since that is what reveals a systematic misfit."]'::jsonb, 2, 'The residual plot is worth including too. The log-log derivative plot is where model error shows up and is the one a reviewer can actually use.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 12, 'What should a report say about an alternative model that fits nearly as well?', '["Omit it, since reporting two answers undermines confidence in the interpretation.", "Mention it only if its residual is within a stated factor of the preferred model''s.", "Report it as the primary result if it is the simpler of the two models.", "State it, and state what it would imply, because the reader is making the decision."]'::jsonb, 3, 'Reporting a single answer where the data support two is a suppressed result rather than confidence.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Which claim should NOT appear in a well test report?', '["A permeability quoted to two significant figures with the window stated.", "A fracture half-length quoted without stating the permeability it assumed.", "An absolute open flow with the method named and the tested rate range given.", "A drainage area with the total compressibility used and its source."]'::jsonb, 1, 'The half-length scales with the square root of the assumed permeability, so a bare number is a measurement times a guess presented as a measurement.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Where does a well test permeability go once it leaves the report?', '["Into the inflow performance relationship, the simulation model and the well count.", "Into the volumetric estimate, since permeability is one of the inputs to oil in place.", "Into the decline curve forecast, which uses it to set the initial decline rate.", "Into the material balance, where it constrains the aquifer influx calculation."]'::jsonb, 0, 'The drainage volume feeds material balance and reserves. Permeability feeds rate calculations, and the skin feeds a stimulation candidate ranking.'),
  ('welltest', 'advanced', 'module', 'm06-the-expert-reading', 15, 'What is the chain an interpretation should be written as?', '["Objective, data, method, calculation, result, comparison, conclusion, recommendation.", "Rate history, pressure history, window, slope, permeability, skin, flow efficiency, report.", "Data, preparation, diagnosis, model, fit, parameters, uncertainty, alternatives.", "Gauge, calibration, decimation, despiking, derivative, regime, model, answer."]'::jsonb, 2, 'Every failure in the course happened at a link that was not written down, and none of them was an arithmetic error.'),
  ('welltest', 'advanced', 'final', null, 1, 'A fit converges with a residual of 4e-13 on a real gauge record. What do you conclude?', '["The model is exactly right, which is unusual but does happen on very clean tests.", "Something is wrong: synthetic data, too many parameters, or a broken comparison.", "The gauge is exceptionally precise and the reservoir is unusually homogeneous.", "The optimiser has converged prematurely on a flat region of the objective function."]'::jsonb, 1, 'A good fit on real data has visible residual scatter and a residual set by the noise level, with intervals of a few percent on permeability.'),
  ('welltest', 'advanced', 'final', null, 2, 'You fit a homogeneous model and then a sealing-fault model to the same buildup. The second has a lower residual. What does that establish?', '["That a boundary is present, since the improvement cannot be a coincidence.", "That the homogeneous model is wrong, though the fault distance may still be unreliable.", "That the fault distance is well determined, since the fit chose it over doing nothing.", "Nothing, because an extra parameter always lowers the residual."]'::jsonb, 3, 'Comparing models with different parameter counts needs a penalty for the extra ones. What is available and more useful is a perturbation test.'),
  ('welltest', 'advanced', 'final', null, 3, 'How would you test whether a fitted fault distance means anything?', '["Refit on slightly perturbed data or a slightly different window and see whether it moves.", "Check its confidence interval, which is narrow when the parameter is well determined.", "Compare its residual against the model without the fault, using an information criterion.", "Refit with the distance fixed at several values and see how much the residual worsens."]'::jsonb, 0, 'The last of those is a profile likelihood and it is a genuine method. The perturbation test takes two runs and directly answers the question.'),
  ('welltest', 'advanced', 'final', null, 4, 'A regression reports permeability to nine significant figures with an interval five parts in a billion wide. What is that interval measuring?', '["The precision of the permeability, which is genuinely that good on noise-free data.", "The sensitivity of the objective to the permeability, which is a property of the reservoir.", "How well the optimiser converged, given a model assumed to be exactly right.", "The range of permeabilities consistent with the gauge resolution over the fitted window."]'::jsonb, 2, 'It has no term for model error, and none for the rate, thickness, viscosity or compressibility, which on real data dominate by orders of magnitude.'),
  ('welltest', 'advanced', 'final', null, 5, 'The rate used in an analysis was 450 stb/d but the true average was 470. How many of the fit''s confidence intervals fit inside that error?', '["About twenty, since a 4 percent rate error is roughly twenty times the interval width.", "Millions: the interval is parts in a billion, the rate error parts in a hundred.", "None, because the confidence interval already accounts for input uncertainty.", "One, since the interval is constructed to cover the dominant error source."]'::jsonb, 1, 'The permeability is proportional to rate. That comparison is the quickest way to see what the fit''s interval is not telling you.'),
  ('welltest', 'advanced', 'final', null, 6, 'A dual-porosity fit on a homogeneous test returns omega at its bound and converged as false. What do you report?', '["That the fit failed and the data are inadequate to determine the dual-porosity parameters.", "That omega is 1 with a confidence interval running to the bound, which is the honest result.", "That the model is incorrectly implemented, since a converged answer should not sit on a bound.", "That the reservoir is single porosity, evidenced by the model degenerating to it."]'::jsonb, 3, 'A parameter at a bound with the other parameters sensible means the model is over-specified for these data, and a simpler model will fit and converge.'),
  ('welltest', 'advanced', 'final', null, 7, 'Which of the catalog''s models degrades safely when it is not needed?', '["Dual porosity, because omega equal to 1 removes the second porosity entirely.", "The sealing fault, because a very large distance makes the boundary imperceptible.", "The fracture, because a very small half-length reduces it to a vertical well.", "The closed rectangle, because very large boundary distances reproduce the infinite case."]'::jsonb, 0, 'A fault has no null value inside its bounds. A tiny half-length is not a plain wellbore either, and the rectangle''s bounds top out at 50000 ft.'),
  ('welltest', 'advanced', 'final', null, 8, 'A well produced at three rates and was then shut in. What producing time goes into the Horner analysis?', '["The duration of the final rate period alone, since the earlier history has already decayed away.", "The total elapsed time from first production to shut-in, which is the full history.", "Cumulative production divided by the final rate, which here is nearly twice the last period.", "The duration of the longest of the three periods, which dominates the response."]'::jsonb, 2, 'Using the last period''s length is the commonest error in buildup analysis and it is silent, because the Horner plot looks perfectly normal.'),
  ('welltest', 'advanced', 'final', null, 9, 'You analyse the last flow period of a multi-rate history as a fresh drawdown. Which way is the permeability wrong?', '["Low, because the earlier production has already depleted the region the transient is spreading into.", "High, because the earlier steps'' responses are still flattening and make the line look flatter.", "Unbiased, provided the last period is longer than the storage transient.", "High or low depending on whether the last rate was above or below the previous one."]'::jsonb, 1, 'On the fixture it comes out over 40 percent high, with a skin nearly double the truth, at an r squared of 0.9998.'),
  ('welltest', 'advanced', 'final', null, 10, 'What is the superposition time function used by the multi-rate semilog?', '["The cumulative production divided by the current rate, which is material-balance time.", "The elapsed time since the most recent rate change, normalised by the total elapsed time.", "The Horner ratio generalised to several rates by taking the product over the steps.", "A sum of logarithms of the times since each rate change, weighted by the rate changes."]'::jsonb, 3, 'It can decrease with time, can be negative, and has no interpretation as a time. Reading one off its axis is meaningless.'),
  ('welltest', 'advanced', 'final', null, 11, 'Between 2000 and 4000 psia, pressure squared overstates the drive by about a fifth. What follows for an analysis?', '["A permeability from a pressure-squared analysis over that range is wrong by a comparable amount.", "The pressure-squared method should be used with a correction factor of about 0.8 in that range.", "The two methods agree within engineering tolerance and either may be used.", "The error cancels in the ratio, so the permeability is unaffected and only p star moves."]'::jsonb, 0, 'That is why the pseudo-pressure form is the only one worth using as a default. It costs one table lookup and removes the question.'),
  ('welltest', 'advanced', 'final', null, 12, 'A gas analysis returns a formation volume factor of 291227. What is it?', '["A unit error, since a formation volume factor cannot exceed a few reservoir barrels per stock tank barrel.", "The gas expansion factor, which is the reciprocal of the gas formation volume factor.", "An adapter constant that turns the liquid equations into the gas ones.", "The ratio of the pseudo-pressure to the pressure at initial conditions."]'::jsonb, 2, 'It is 1637 T over 162.6 mu, and it has no physical interpretation. A field name in reused code is a claim about the original design, not the current contents.'),
  ('welltest', 'advanced', 'final', null, 13, 'A gas buildup reports p star as 4.8e8. What has gone wrong?', '["The reservoir is over-pressured, which is what a value of that magnitude indicates.", "Nothing, except that somebody forgot to invert it back from pseudo-pressure to pressure.", "The pseudo-pressure table did not extend high enough, so the value was extrapolated.", "The extrapolation ran to a Horner ratio below one, which is not physically meaningful."]'::jsonb, 1, 'The magnitude is the tell. The engine''s gas Horner function returns both the pseudo-pressure and the inverted pressure, and only the second is reportable.'),
  ('welltest', 'advanced', 'final', null, 14, 'Three flow-after-flow points give two absolute open flows four percent apart. Which do you report?', '["The back-pressure value, since its r squared is far higher on the tested points.", "The LIT value alone, since it is derived rather than empirical and is therefore correct.", "Their average, since neither method is preferred and the difference is small.", "Both, with the methods named, since an AOF is an extrapolation and the method is part of it."]'::jsonb, 3, 'LIT is preferred for extrapolation on physical grounds, and back-pressure for continuity with contract precedent. Reporting both costs one extra line.'),
  ('welltest', 'advanced', 'final', null, 15, 'Why does the better r squared not settle which deliverability method to believe?', '["Because the absolute open flow is evaluated well outside the range where there are data.", "Because r squared is computed on log axes for one method and linear axes for the other.", "Because three points cannot support a meaningful r squared for either method.", "Because the LIT form fits a derived equation, so its residual has a different meaning."]'::jsonb, 0, 'The tested pressure-squared differences run to about 2.1 million and the AOF is evaluated at about 3.8 million. A fit statistic is silent about a region it never saw.'),
  ('welltest', 'advanced', 'final', null, 16, 'A production record shows material-balance time reaching 2354 days over an 80-day history. What do you do?', '["Cap it at the elapsed time, since a time transform cannot exceed the record length.", "Recompute the cumulative, since a value that large indicates an integration error.", "Use it, because the transform is doing exactly what it is defined to do.", "Switch to elapsed time, since material-balance time has clearly broken down."]'::jsonb, 2, 'The rate has fallen a long way and the cumulative divided by a small current rate is large. The well has depleted as much as a constant-rate well would have by then.'),
  ('welltest', 'advanced', 'final', null, 17, 'A flowing material balance gives an N well above the volumetric estimate. What is the most likely cause?', '["The total compressibility used was too high, which inflates the oil in place.", "The record is not yet boundary dominated, so the fit has caught the transient.", "The initial pressure used was too low, which reduces the drawdown and raises N.", "The productivity index has fallen, which flattens the line and raises the slope."]'::jsonb, 1, 'Transient data have a shallower slope than the depletion line, and N is one over the slope times ct, so an included transient always makes N too large.'),
  ('welltest', 'advanced', 'final', null, 18, 'Which quantity from a rate transient analysis is a per-well property that changes over time?', '["The connected volume N, which changes when an infill well is drilled or a neighbour is shut in.", "The productivity index J, which is fixed by the completion and the rock.", "The total compressibility, which falls as the reservoir depletes below the bubble point.", "The material-balance time, which is a property of the production record rather than the well."]'::jsonb, 0, 'J degrades over time as the skin grows or the relative permeability to oil falls, and tracking it month by month is one of the most useful things a production engineer can do.'),
  ('welltest', 'advanced', 'final', null, 19, 'A gas rate transient returns a G twice what the volumetrics suggest. What do you check first?', '["Whether the gas gravity used matches the produced gas, since it enters the pseudo-pressure.", "Whether the initial pressure is right, since it sets the drawdown at every point.", "Whether the iteration converged, since a non-converged G can be arbitrarily wrong.", "Whether pseudo-time was used, since plain material-balance time can nearly halve the slope."]'::jsonb, 3, 'On the fixture, pseudo-time is about half of material-balance time at the last row. That is the largest single factor available to explain a factor-of-two error.'),
  ('welltest', 'advanced', 'final', null, 20, 'The dynamic material balance iterates. What is it iterating on?', '["The pseudo-pressure table, which is refined at each step to match the depletion path.", "The productivity index, which enters the intercept and is not known in advance.", "The gas in place, because pseudo-time needs the average pressure which needs the gas in place.", "The initial compressibility, which itself depends on the pressure and therefore on the depletion."]'::jsonb, 2, 'Guess G, get the average pressure from the material balance, compute pseudo-time, regress, get a new G. It converges in fifteen iterations on this fixture.'),
  ('welltest', 'advanced', 'final', null, 21, 'A linear-flow analysis gives xf times root k of 500. The permeability is thought to be 0.01 mD. What is the half-length?', '["50 ft, because dividing by the square root of 0.01 divides by ten.", "5000 ft, because dividing by the square root of 0.01 multiplies by ten.", "500 ft, since the permeability enters only through the product and cancels.", "It cannot be found, since the analysis measures a product and not the two quantities."]'::jsonb, 1, 'It cannot be found from that analysis ALONE, which is why the permeability has to be assumed and why the assumption belongs in the report.'),
  ('welltest', 'advanced', 'final', null, 22, 'Why does more linear-flow data not separate xf from k?', '["Because the degeneracy is in the physics of the regime rather than in the quantity of data.", "Because the noise floor is reached quickly, after which more data add nothing.", "Because the two parameters are perfectly correlated in the least squares sense only for exact data.", "Because linear flow ends before the two parameters begin to influence the response separately."]'::jsonb, 0, 'Only a different regime, such as boundary-dominated flow, or a different measurement, such as a permeability from radial flow, resolves it.'),
  ('welltest', 'advanced', 'final', null, 23, 'Which of these is an honest way to report a fracture half-length from linear flow?', '["A single half-length using the field''s average permeability, with the average stated.", "A range of half-lengths from the fit''s confidence interval on the slope.", "The half-length that matches the fracture design, since that is the independent estimate.", "The measured product, and a table of half-lengths against assumed permeability."]'::jsonb, 3, 'A single half-length quoted without the permeability it assumed is a measurement times a guess, presented as a measurement.'),
  ('welltest', 'advanced', 'final', null, 24, 'What did the horizontal well fixture show about the standoff parameter?', '["That it is well determined, since the top and bottom boundaries are at different distances.", "That it is unbounded, so the optimiser drives it to its limit and reports non-convergence.", "That the fit stays on whichever side it started, and the wrong side fits better.", "That it is correlated with the well length, so only their product can be recovered."]'::jsonb, 2, 'The slab''s two no-flow boundaries make the standoff nearly a mirror. The two forward responses differ by at most about two hundredths of a percent over the whole test.'),
  ('welltest', 'advanced', 'final', null, 25, 'A parameter whose fitted value depends on the starting guess. What is that?', '["An optimiser bug, since a correctly implemented least squares converges from anywhere.", "An objective with more than one minimum, or a nearly flat direction.", "A poorly scaled parameter, which log scaling in the catalog is designed to prevent.", "A bound that is too tight, trapping the optimiser in the region it started in."]'::jsonb, 1, 'On the buildup, starting from 5 mD and 0.5 bbl per psi lands in the same place, which is what a well-conditioned problem looks like. The horizontal standoff does not.'),
  ('welltest', 'advanced', 'final', null, 26, 'Which residual definition does the engine minimise?', '["The logarithm of the ratio of model to data, for both the pressure and the derivative.", "The squared difference between model and data pressures, weighted by the derivative.", "The relative difference, which is the log residual to first order but bounded at plus or minus one.", "The difference in log-log space between the two curves, measured perpendicular to the model."]'::jsonb, 0, 'A log residual makes a one percent discrepancy contribute the same amount wherever it occurs, which is why fits are shown on log-log axes.'),
  ('welltest', 'advanced', 'final', null, 27, 'Why does the engine charge a fixed penalty when a model value is non-positive?', '["To signal to the caller that the parameter bounds may need widening for this particular dataset.", "To ensure the residual vector has a constant length, which the solver requires.", "To weight those points more heavily so the optimiser moves away from them faster.", "To keep the optimiser out of non-physical regions without letting the logarithm fail."]'::jsonb, 3, 'It is a standard device. The penalty value of 5 is arbitrary and only has to be large relative to a typical log residual.'),
  ('welltest', 'advanced', 'final', null, 28, 'What is the practical meaning of a parameter fitted on a logarithmic scale?', '["Its steps are smaller near zero, which improves convergence for small values.", "Its bounds are enforced exactly, which linear scaling cannot guarantee.", "Its confidence interval becomes multiplicative rather than additive.", "Its correlation with other parameters is removed, which conditions the problem."]'::jsonb, 2, 'It also enforces positivity for free: there is no value of the logarithm that gives a negative permeability.'),
  ('welltest', 'advanced', 'final', null, 29, 'A fit on the fault fixture gives a distance 0.76 percent below the planted 800 ft. What does that show?', '["That the model''s image-well implementation carries a systematic bias of about one percent.", "That a well-posed fit on a boundary the data really contain recovers it well.", "That the fitted distance is as unreliable as the phantom fault''s, since both are boundary parameters.", "That the derivative weighting biases boundary distances low by about one percent."]'::jsonb, 1, 'It also moves by about two hundredths of a foot under the rewrite that moves the phantom fault 116 ft. Constrained parameters do not move.'),
  ('welltest', 'advanced', 'final', null, 30, 'A fit''s smoothing window is changed from 0.1 to 0.15 and a fitted fault distance moves three feet. What does that mean for a capstone?', '["The settings have to be stated, because the quantity is not settings independent.", "The fit is unstable and the parameter should not be graded at any setting.", "The change is inside any reasonable tolerance and can be ignored.", "The smoothing should be set to zero so that no setting has to be stated."]'::jsonb, 0, 'Three feet is outside the graded tolerance. In practice you choose the setting and defend it; in a capstone it is given so that the answers are comparable.'),
  ('welltest', 'advanced', 'final', null, 31, 'What is the one capstone field you can compute on paper?', '["The multi-rate permeability, once the superposition time function is tabulated.", "The deliverability disagreement, since both fits are straight lines through three points.", "The oil in place, since the flowing material balance is a two-point straight line.", "The equivalent producing time, which is cumulative rate-hours divided by the last rate."]'::jsonb, 3, 'The deliverability fits are straight lines and the arithmetic is heavy. The producing time is one division.'),
  ('welltest', 'advanced', 'final', null, 32, 'Which two capstone fields are volumes, and how well are they recovered?', '["The drainage area and the pore volume, both to a few thousandths of a percent.", "Oil in place and the fault distance, one to a fraction of a percent and one to one percent.", "Oil in place and gas in place, both within a fraction of a percent.", "Gas in place and the absolute open flow, both to about four percent."]'::jsonb, 2, 'The drainage area belongs to the Professional tier. Two volumes recovered to a fraction of a percent, three capacity or geometry quantities to a couple of percent, and one disagreement between methods.'),
  ('welltest', 'advanced', 'final', null, 33, 'What kind of quantity is the deliverability disagreement field?', '["A measurement of the non-Darcy coefficient, expressed as a percentage of the laminar term.", "Not a recovery of anything: its existence is the result.", "An estimate of the uncertainty in the absolute open flow from the three tested points.", "A check that both fits were performed correctly, since a correct pair agrees to four percent."]'::jsonb, 1, 'Two accepted methods, the same three clean points, and answers four percent apart. That is a floor on the uncertainty of an AOF rather than a property of the well.'),
  ('welltest', 'advanced', 'final', null, 34, 'Which is the honest summary of what well test analysis delivers?', '["Volumes to a fraction of a percent, capacities to a few percent, and some things not at all.", "Permeability and skin to two significant figures, and everything else to one.", "Whatever the model catalog contains, to the precision the confidence intervals state.", "A diagnosis, which is qualitative, plus parameters whose accuracy cannot be assessed."]'::jsonb, 0, 'The accuracy of each quantity follows from whether it comes from an equilibrium, an asymptote, an extrapolation or a parameter the data barely constrain.'),
  ('welltest', 'advanced', 'final', null, 35, 'A report claims a permeability to five significant figures from a model fit. What is the objection?', '["The fit''s confidence interval does not support five figures on real data.", "Permeability should always be reported as a flow capacity, which needs no thickness.", "Five figures implies the thickness is known to five figures, which it never is.", "Two valid analyses of the same well disagree in the second figure, so the fifth is fiction."]'::jsonb, 3, 'The confidence interval on real data would not support it either, and neither would the input uncertainties. The disagreement between valid analyses is the most direct evidence.'),
  ('welltest', 'advanced', 'final', null, 36, 'What is the strongest argument for reporting the rate history alongside an interpretation?', '["Because the rate is metered and therefore the most reliable measurement in the test.", "Because a reader can recompute the cumulative production and check the material balance.", "Because the analysis depends on information that is not in the pressure record at all.", "Because superposition requires the rate history, and the reader may wish to redo the fit."]'::jsonb, 2, 'Ignoring it costs 40 percent on permeability on this course''s fixture, and no shape-based diagnostic finds a rate error.'),
  ('welltest', 'advanced', 'final', null, 37, 'You have a buildup and two years of production data on the same well. What do you do?', '["Analyse the buildup, since a controlled test is more reliable than allocated production data.", "Analyse both, because one gives flow capacity and skin and the other gives the connected volume.", "Analyse the production data, since two years reaches boundaries a three-day buildup cannot.", "Analyse whichever gives the answer closer to the field''s mapped properties."]'::jsonb, 1, 'A field with both is much better characterised than one with either. The two answer different questions.'),
  ('welltest', 'advanced', 'final', null, 38, 'Which of these is NOT in the engine?', '["Deconvolution of a variable-rate history into a constant-rate response.", "Levenberg-Marquardt regression of a catalog model onto pressure and derivative data.", "The dynamic material balance for gas, iterating on the gas in place.", "Rawlins-Schellhardt and Houpeurt deliverability fits with absolute open flow."]'::jsonb, 0, 'Nor interference testing, nor a separation of the apparent skin into its Darcy and non-Darcy parts. All three are taught and none is graded.'),
  ('welltest', 'advanced', 'final', null, 39, 'Why does the course state its refusals explicitly rather than simply omitting the topics?', '["Because a certificate has to enumerate what it does and does not cover, for accreditation.", "Because the omitted topics would otherwise be assumed to be included in the engine.", "Because the go-live migration needs a list of forbidden field keys to assert against.", "Because teaching a topic and certifying a learner can produce its answer are different claims."]'::jsonb, 3, 'The migration''s assertion turns the commitment into a check, which is a consequence of stating the scope rather than the reason for it.'),
  ('welltest', 'advanced', 'final', null, 40, 'A colleague reports a fault at 3100 ft with a 40 ft confidence interval from a model fit. What is your first question?', '["What the residual was, since a phantom fault has a much larger residual than a real one.", "Whether the fit converged, since a phantom fault typically fails to converge.", "What the derivative showed, since a boundary parameter with no boundary is a phantom.", "What the starting value was, since a fault distance usually stays near where it started."]'::jsonb, 2, 'The phantom fault on this course''s buildup converges, has a tiny residual and reports a tight interval. Only the diagnosis catches it.'),
  ('welltest', 'advanced', 'final', null, 41, 'An interpretation is delivered with no diagnosis section. What is the practical consequence?', '["A reader cannot tell whether the model was justified, which was the real decision.", "The result is unusable, since the diagnosis is what determines the parameter values.", "Nothing, provided the fit converged and the residual is at the noise level.", "The uncertainty cannot be quantified, since the diagnosis sets the model error term."]'::jsonb, 0, 'The parameters follow from the fit. Which model was fitted, and why, is the interpretation, and a report that hides it has hidden the decision.'),
  ('welltest', 'advanced', 'final', null, 42, 'What separates a parameter that is measured from one that is merely reported?', '["Whether it appears in the model''s equations rather than being derived afterwards.", "Whether the data constrain it, which a perturbation test answers and the interval does not.", "Whether its own confidence interval excludes the value that would remove it from the model.", "Whether it was fitted rather than fixed at a value taken from another source."]'::jsonb, 1, 'That distinction is the Expert tier in one line, and it is why the course grades the fault that is there and teaches the one that is not.');
